package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.HandlerInstantiator;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedField;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.introspect.POJOPropertyBuilder;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.util.BeanUtil;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class POJOPropertiesCollector__addInjectables_TriageGen0Test {

    private POJOPropertiesCollector collector;
    private MapperConfig<?> mockConfig;
    private JavaType mockType;
    private AnnotatedClass mockClassDef;
    private AnnotationIntrospector mockAi;
    private Map<String, POJOPropertyBuilder> props;

    // Subclass to expose the protected method for testing and to mock internal calls
    private static class TestablePOJOPropertiesCollector extends POJOPropertiesCollector {
        private final AnnotationIntrospector aiToSet;

        public TestablePOJOPropertiesCollector(MapperConfig<?> config, boolean forSerialization, JavaType type, 
                                              AnnotatedClass classDef, String mutatorPrefix, AnnotationIntrospector ai) {
            super(config, forSerialization, type, classDef, mutatorPrefix);
            this.aiToSet = ai;
            // Since _annotationIntrospector is private in the real class, 
            // in a real scenario we'd use reflection or rely on the constructor/config.
            // For this test, we assume we can set it via reflection or it's provided by the environment.
        }

        // We override to simulate the behavior of the private field _annotationIntrospector
        // because we cannot access it directly in the test class.
        @Override
        public AnnotationIntrospector getAnnotationIntrospector() {
            return aiToSet;
        }

        // We spy on the collector to intercept _doAddInjectable
        public void injectAi(AnnotationIntrospector ai) throws Exception {
            java.lang.reflect.Field field = POJOPropertiesCollector.class.getDeclaredField("_annotationIntrospector");
            field.setAccessible(true);
            field.set(this, ai);
        }
    }

    @Before
    public void setUp() throws Exception {
        mockConfig = mock(MapperConfig.class);
        mockType = mock(JavaType.class);
        mockClassDef = mock(AnnotatedClass.class);
        mockAi = mock(AnnotationIntrospector.class);
        props = new HashMap<>();

        collector = spy(new TestablePOJOPropertiesCollector(mockConfig, true, mockType, mockClassDef, "", mockAi));
        collector.injectAi(mockAi);
    }

    @Test
    public void testAddInjectables_NullAi() throws Exception {
        // Set AI to null
        java.lang.reflect.Field field = POJOPropertiesCollector.class.getDeclaredField("_annotationIntrospector");
        field.setAccessible(true);
        field.set(collector, null);

        collector._addInjectables(props);

        // Verify no interactions with classDef
        verifyZeroInteractions(mockClassDef);
    }

    @Test
    public void testAddInjectables_FieldsAndMethods() {
        // Mock Fields
        AnnotatedField field1 = mock(AnnotatedField.class);
        AnnotatedField field2 = mock(AnnotatedField.class);
        when(mockClassDef.fields()).thenReturn(java.util.Arrays.asList(field1, field2));

        // Mock Methods
        AnnotatedMethod method1 = mock(AnnotatedMethod.class); // 1 param (valid)
        AnnotatedMethod method2 = mock(AnnotatedMethod.class); // 0 params (invalid)
        AnnotatedMethod method3 = mock(AnnotatedMethod.class); // 2 params (invalid)

        when(method1.getParameterCount()).thenReturn(1);
        when(method2.getParameterCount()).thenReturn(0);
        when(method3.getParameterCount()).thenReturn(2);

        when(mockClassDef.memberMethods()).thenReturn(java.util.Arrays.asList(method1, method2, method3));

        // Mock AI responses
        Object fieldId1 = "fieldId1";
        Object fieldId2 = "fieldId2";
        Object methodId1 = "methodId1";

        when(mockAi.findInjectableValueId(field1)).thenReturn(fieldId1);
        when(mockAi.findInjectableValueId(field2)).thenReturn(fieldId2);
        when(mockAi.findInjectableValueId(method1)).thenReturn(methodId1);
        // method2 and method3 should be skipped before findInjectableValueId is called

        // Execute
        collector._addInjectables(props);

        // Verify _doAddInjectable calls
        verify(collector)._doAddInjectable(fieldId1, field1);
        verify(collector)._doAddInjectable(fieldId2, field2);
        verify(collector)._doAddInjectable(methodId1, method1);

        // Verify method2 and method3 were skipped (findInjectableValueId not called for them)
        verify(mockAi, never()).findInjectableValueId(method2);
        verify(mockAi, never()).findInjectableValueId(method3);
    }

    @Test
    public void testAddInjectables_NoFieldsNoMethods() {
        when(mockClassDef.fields()).thenReturn(Collections.emptyList());
        when(mockClassDef.memberMethods()).thenReturn(Collections.emptyList());

        collector._addInjectables(props);

        verify(collector, never())._doAddInjectable(any(), any());
    }
}
